    "contentHtml": "<section class=\"ea-content-item  easyadmin-modules-core-pagecontent-types-texttype \">\n        <div class=\"container\">\n                <div class=\"text-type\">\n    <div class=\"rte\">\n        <p>Aktuální rozvrh a další informace naleznete <b><a class=\"ealink\" eaidnode=\"\" href=\"https://ksirovka.isportsystem.cz/#ui-tabs-0\" target=\"_blank\">ZDE</a></b>.</p>\n\n    </div>\n</div>\n\n\n\n\n        </div>\n    </section>",
